function klaerfallSchliessen(db, schluessel, text) {
  for (const k of db.finanzen.klaerfaelle.filter((x) => x.schluessel === schluessel && x.status === "offen")) {
    k.status = "erledigt";
    k.erledigtAm = jetzt();
