    provisionen: db.provisionen.filter((x) => x.anbieterId === u.id).map((x) => ({ id: x.id, projektId: x.projektId, satz: x.satz, betrag: x.betrag, status: x.status, erstelltAm: x.erstelltAm })),
    nachrichten: db.nachrichten
