// Betrag symmetrisch runden (auch Gutschriften/negative Beträge: −1,005 → −1,01, nicht −1,00)
export const rund = (x, stellen = 2) => {
  const f = 10 ** stellen;
  const r = (Math.sign(Number(x)) * Math.round((Math.abs(Number(x)) + Number.EPSILON) * f)) / f;
