    .sort((a, b) => String(a.erstelltAm).localeCompare(String(b.erstelltAm)));
  return {
    moderation: fragen.filter((f) => ["eingereicht", "beantwortet"].includes(f.status)),
    beimAnbieter: fragen.filter((f) => f.status === "freigegeben"),
