/** Offene-Posten-Liste als Excel-CSV (UTF-8 mit BOM, Formel-Schutz) */
export function opCsv(liste) {
  const w = (v) => {
    let s = v === null || v === undefined ? "" : typeof v === "number" ? String(rund2(v)).replace(".", ",") : String(v);
    if (typeof v !== "number" && /^[=+\-@\t\r]/.test(s)) s = `'${s}`;
