cd /c/Users/SALEADMIN/Downloads/Oekoinvest-Web && python - <<'E'
import os
R={}
W='import { route } from "@/lib/plattform/server/route";\nimport { werkzeugeBackend } from "@/lib/plattform/backend/werkzeuge";\n'
datei='''const datei = (text, name, typ, latin1 = false) => new Response(latin1 ? Buffer.from(text, "latin1") : text, { headers: { "Content-Type": typ, "Content-Disposition": `attachment; filename="${name}"`, "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff" } });
'''
pdfh='''const pdfAntwort = (pdf, name, anzeigen) => new Response(pdf, { headers: { "Content-Type": "application/pdf", "Content-Disposition": `${anzeigen ? "inline" : "attachment"}; filename="${name.replace(/[^A-Za-z0-9._-]/g, "_")}"`, "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff", "Content-Security-Policy": "sandbox" } });
'''
b='src/app/api/admin/finanzen/buchhaltung'
R[f'{b}/route.js']='// GET /api/admin/finanzen/buchhaltung – Übersicht Buchhaltung: OP-Liste, Mahnvorschläge, Zahlungseingänge, Stornos, Nummernkreise, Steuer-Check\n'+W+'\nexport const GET = route({ admin: true }, async ({ nutzer }) => ({ ok: true, ...(await werkzeugeBackend().bhUebersicht(nutzer)) }));\n'
R[f'{b}/einstellungen/route.js']='// POST /api/admin/finanzen/buchhaltung/einstellungen – { mahnwesen?, konten? } (Bereich „finanzen“ schreiben)\n'+W+'\nexport const POST = route({ admin: true }, async ({ nutzer, body }) => werkzeugeBackend().bhEinstellungenSpeichern(nutzer, { mahnwesen: body.mahnwesen, konten: body.konten }));\n'
R[f'{b}/mahnlauf/route.js']='// POST /api/admin/finanzen/buchhaltung/mahnlauf – { ids?: [Beleg-IDs], trockenlauf? } → Mahnbelege (MA-Nummer) für fällige Vorschläge\n'+W+'\nexport const POST = route({ admin: true }, async ({ nutzer, body }) => ({ ok: true, ...(await werkzeugeBackend().bhMahnlauf(nutzer, { ids: body.ids, trockenlauf: body.trockenlauf })) }));\n'
R[f'{b}/belege/[id]/route.js']='''// POST /api/admin/finanzen/buchhaltung/belege/[id] – { aktion: "storno", grund, provisionStornieren? } | { aktion: "mahnsperre", bis?, grund? }
'''+W+'''import { PlattformFehler } from "@/lib/plattform/fehler";

export const POST = route({ admin: true }, async ({ nutzer, params, body }) => {
  const b = werkzeugeBackend();
  if (body.aktion === "storno") return b.bhStorno(nutzer, params.id, { grund: body.grund, provisionStornieren: body.provisionStornieren });
  if (body.aktion === "mahnsperre") return b.bhMahnsperre(nutzer, params.id, { bis: body.bis, grund: body.grund });
  throw new PlattformFehler(400, "Unbekannte Aktion.");
});
