// src/components/Portal/Anlagen/Reiter.js – Reiter einer Anlage als Links (?tab=), mobil horizontal scrollbar

import Link from "next/link";
import { cn } from "@/components/ui/cn";

export default function Reiter({ basis, aktiv, tabs = [], label = "Bereiche der Anlage" }) {
  return (
    <nav aria-label={label} className="-mx-4 mb-6 overflow-x-auto px-4 ov-no-scrollbar md:mx-0 md:px-0">
      <ul className="flex min-w-max gap-1.5 rounded-full bg-white p-1.5 ring-1 ring-ink-200/70 md:min-w-0 md:flex-wrap">
        {tabs.map((t) => {
          const an = t.id === aktiv;
          const Icon = t.icon;
          return (
            <li key={t.id}>
              <Link
                href={`${basis}${t.id === "uebersicht" ? "" : `?tab=${t.id}`}`}
                aria-current={an ? "page" : undefined}
                scroll={false}
                className={cn("inline-flex h-10 items-center gap-2 whitespace-nowrap rounded-full px-4 text-[14px] font-semibold transition-colors", an ? "bg-navy-900 text-white" : "text-ink-700 hover:bg-ink-50")}
              >
                {Icon && <Icon aria-hidden="true" className="h-4 w-4" />}
                {t.label}
                {t.zaehler ? <span className={cn("ov-num rounded-full px-1.5 text-[11.5px] font-bold", an ? "bg-white/20 text-white" : "bg-red-600 text-white")}>{t.zaehler}</span> : null}
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
// src/components/Portal/ui.js
//
// Bausteine des Portals (Server- und Client-tauglich, ohne Hooks).
// Nur Tokens des Design-Systems: ov-*, navy-*, ink-*, sand-*, sun-* (sparsam).

import Link from "next/link";
import { ArrowRight, Check, Circle } from "lucide-react";
import { cn } from "@/components/ui/cn";
import { PROZESSE, statusInfo } from "@/lib/plattform/prozesse";
import { datumZeit } from "@/lib/plattform/format";

const TOENE = {
  neutral: "bg-ink-100 text-ink-700 ring-ink-200",
  info: "bg-navy-50 text-navy-700 ring-navy-100",
  ok: "bg-ov-50 text-ov-800 ring-ov-200",
  warn: "bg-sun-300/25 text-ink-900 ring-sun-400/50",
  dunkel: "bg-navy-900 text-white ring-navy-800",
};

export function Badge({ ton = "neutral", children, className }) {
  return (
    <span className={cn("inline-flex items-center gap-1.5 whitespace-nowrap rounded-full px-2.5 py-1 text-[12px] font-semibold ring-1 ring-inset", TOENE[ton] || TOENE.neutral, className)}>
      {children}
    </span>
  );
}

export function StatusBadge({ art, status, className }) {
  const s = statusInfo(art, status);
  return (
    <Badge ton={s.ton} className={className}>
      <span aria-hidden="true" className={cn("h-1.5 w-1.5 rounded-full", s.ton === "ok" ? "bg-ov-500" : s.ton === "warn" ? "bg-sun-500" : s.ton === "info" ? "bg-navy-500" : "bg-ink-400")} />
      {s.label}
    </Badge>
  );
}

export function DemoBadge({ className }) {
  return <Badge ton="warn" className={className}>Demo</Badge>;
}

/** Weiße Karte mit optionalem Kopf */
export function Karte({ titel, untertitel, aktion, children, className, innen = "p-5 md:p-6", as: Tag = "section", id }) {
  return (
    <Tag id={id} className={cn("min-w-0 rounded-3xl bg-white ring-1 ring-ink-200/70", className)}>
      {(titel || aktion) && (
        <div className="flex flex-wrap items-start justify-between gap-3 border-b border-ink-100 px-5 py-4 md:px-6">
          <div className="min-w-0">
            {titel && <h2 className="font-display text-[17px] font-bold text-ink-900">{titel}</h2>}
            {untertitel && <p className="mt-0.5 text-[13.5px] text-ink-500">{untertitel}</p>}
          </div>
          {aktion}
        </div>
      )}
      <div className={innen}>{children}</div>
    </Tag>
  );
}

/** Kopf einer Portalseite */
// src/lib/plattform/client.js
//
// fetch-Helfer für Client-Komponenten. Mutationen immer als JSON (CSRF-Schutz
// über Content-Type + Origin, siehe server/route.js); Uploads mit Kopfzeile.

export async function senden(url, { method = "POST", body } = {}) {
  let res;
  try {
    res = await fetch(url, {
      method,
      headers: body !== undefined ? { "Content-Type": "application/json" } : undefined,
      body: body !== undefined ? JSON.stringify(body) : undefined,
      credentials: "same-origin",
      cache: "no-store",
    });
  } catch {
    throw new Error("Keine Verbindung – bitte prüfen Sie Ihre Internetverbindung.");
  }
  const json = await res.json().catch(() => ({}));
  if (!res.ok || json.ok === false) {
    const e = new Error(json.error || `Fehler ${res.status}`);
    e.status = res.status;
    throw e;
  }
  return json;
}

export async function hochladen(datei, { bezugArt, bezugId, kategorie = "allgemein", checkliste = "", anhang = false }) {
  const fd = new FormData();
  fd.append("datei", datei);

