  return (
    <form className="space-y-3" onSubmit={(e) => { e.preventDefault(); ausfuehren(() => senden(ziel, { body: d }), (r) => `${r.id} erfasst. ${r.hinweis}`); }}>
      <div className="grid gap-3 sm:grid-cols-2">
