// Prüft benannte Importe der eigenen Dateien gegen die Exporte der Zieldateien (grob, per Regex)
import fs from "node:fs";
import path from "node:path";
const ROOT = "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web";
const dateien = process.argv.slice(2);
const exporteCache = new Map();
function aufloesen(von, spez) {
  let p = spez.startsWith("@/") ? path.join(ROOT, "src", spez.slice(2)) : spez.startsWith(".") ? path.resolve(path.dirname(von), spez) : null;
  if (!p) return null;
  for (const k of ["", ".js", ".mjs", "/index.js"]) if (fs.existsSync(p + k) && fs.statSync(p + k).isFile()) return p + k;
  return "FEHLT:" + p;
}
function exporte(datei, tiefe = 0) {
  if (exporteCache.has(datei)) return exporteCache.get(datei);
  const s = fs.readFileSync(datei, "utf8");
  const set = new Set();
  for (const m of s.matchAll(/export\s+(?:async\s+)?(?:function\*?|const|let|class)\s+([A-Za-z0-9_$]+)/g)) set.add(m[1]);
  for (const m of s.matchAll(/export\s*\{([^}]*)\}/g)) for (const t of m[1].split(",")) { const n = t.trim().split(/\s+as\s+/).pop(); if (n) set.add(n); }
  if (/export\s+default/.test(s)) set.add("default");
  for (const m of s.matchAll(/export\s+\*\s+from\s+"([^"]+)"/g)) { const z = aufloesen(datei, m[1]); if (z && !z.startsWith("FEHLT") && tiefe < 5) for (const x of exporte(z, tiefe + 1)) set.add(x); }
  exporteCache.set(datei, set);
  return set;
}
let fehler = 0;
for (const d of dateien) {
  const s = fs.readFileSync(d, "utf8");
  for (const m of s.matchAll(/import\s+(?:([A-Za-z0-9_$]+)\s*,?\s*)?(?:\{([^}]*)\})?\s*(?:\*\s+as\s+\w+\s*)?from\s+"([^"]+)"/g)) {
    const z = aufloesen(d, m[3]);
    if (!z) continue;
    if (z.startsWith("FEHLT")) { console.log(`${d}: Modul fehlt ${m[3]}`); fehler++; continue; }
    const ex = exporte(z);
    const namen = (m[2] || "").split(",").map((t) => t.trim().split(/\s+as\s+/)[0]).filter(Boolean);
    if (m[1]) namen.push("default");
    for (const n of namen) if (!ex.has(n)) { console.log(`${path.relative(ROOT, d)}: ${n} nicht exportiert von ${m[3]}`); fehler++; }
  }
}
console.log(fehler ? `${fehler} Probleme` : "Importe ok");

