# ================================================================ Monatsabschluss

ABSCHLUSS_PUNKTE = [
	("contracting_lauf", "Contracting-Abrechnung des Monats erstellt", True, True, "Abrechnungslauf Contracting für den Monat ausgeführt (Monatswerte der Messpunkte)."),
