	felder = {}
	akt = d.get("aktion")
	if akt == "notiz":
		t = v.mehrzeilig(d.get("text"), 2000).strip()
		if len(t) < 5:
			ungueltig("Bitte eine Notiz eingeben.")
		verlauf.append({"am": iso(now_datetime()), "vonId": n.id, "text": t})
	else:
		p = C.verdacht_uebergang(f, akt, d, heute, n.id)
		if not p["ok"]:
