79	    if (p.typ === "rechnung") aus.push({ ...basis, betrag: rund2(p.brutto), soll: k.debitor, haben: erloes(p) });
80	    else if (p.typ === "gutschrift") aus.push({ ...basis, betrag: rund2(p.brutto), soll: k.aufwand.pacht, haben: k.kreditor });
81	    else if (p.typ === "storno") {
82	      // Storno kehrt die Ursprungsbuchung um (Rechnung: Erlös an Debitor; Gutschrift: Kreditor an Aufwand)
83	      if (p.ursprung === "gutschrift") aus.push({ ...basis, betrag: rund2(Math.abs(p.brutto)), soll: k.kreditor, haben: k.aufwand.pacht });
84	      else aus.push({ ...basis, betrag: rund2(Math.abs(p.brutto)), soll: erloes(p), haben: k.debitor });
85	    } else if (p.typ === "zahlung") {
86	      if (p.richtung === "ausgang") aus.push({ ...basis, steuerVorlage: "", steuerBetrag: 0, betrag: rund2(p.brutto), soll: k.kreditor, haben: k.bank });
87	      else aus.push({ ...basis, steuerVorlage: "", steuerBetrag: 0, betrag: rund2(p.brutto), soll: k.bank, haben: k.debitor });
88	    }
89	  }
90	  return aus.filter((b) => b.betrag > 0).sort((a, b) => String(a.datum).localeCompare(String(b.datum)) || String(a.beleg).localeCompare(String(b.beleg)));
