export function ibanMaskieren(iban) {
  const i = ibanNormalisieren(iban);
  if (i.length < 8) return i ? "****" : "";
  const mitte = i.slice(4, -4).replace(/./g, "*");
  return `${i.slice(0, 4)}${mitte}${i.slice(-4)}`.replace(/(.{4})/g, "$1 ").trim();
}

/**
 * Text auf den SEPA-Zeichensatz (EPC: a–z A–Z 0–9 / - ? : ( ) . , ' + Leerzeichen) bringen: Umlaute umschreiben,
 * alles andere durch Leerzeichen ersetzen, kürzen.
 */
1:// GET  /api/portal/benachrichtigungen?ungelesen=1&limit=  – eigene Benachrichtigungen (Glocke) + Einstellungen
8:  ...(await backend.benachrichtigungen(nutzer, { nurUngelesen: suche.get("ungelesen") === "1", limit: Math.min(200, Number(suche.get("limit")) || 50) })),

export function auswahl(v, erlaubt, standard = "") {
  const liste = Array.isArray(erlaubt) ? erlaubt : Object.keys(erlaubt);
  return liste.includes(v) ? v : standard;
}

export function mehrfach(v, erlaubt) {
  const liste = Array.isArray(erlaubt) ? erlaubt : Object.keys(erlaubt);
  return Array.isArray(v) ? [...new Set(v.filter((x) => liste.includes(x)))] : [];
}

export const wahr = (v) => v === true || v === "true" || v === "on" || v === 1;

export const kennung = (v) => (/^[A-Z]{1,3}-[0-9A-Z-]{4,40}$/.test(String(v || "")) ? String(v) : "");

